#![allow(clippy::unwrap_used, clippy::expect_used)]
//! `GameConfig` (generated by `codegen config`, M2-GEN-02): loading, defaults and spot checks.
//!
//! The tests that read the real `dist/game/config` folder skip with a message when the Java
//! checkout is missing (CI). The rest runs everywhere.

use std::path::{Path, PathBuf};

use l2_config::game::CLASSES;
use l2_config::{GameConfig, IniFile};

/// `$L2J_ROOT/dist/game/config`, if the Java checkout exists.
fn dist_config_dir() -> Option<PathBuf> {
    let root = std::env::var("L2J_ROOT").unwrap_or_else(|_| r"C:\l2-rust\l2jmobius".to_string());
    let dir = Path::new(&root).join("dist").join("game").join("config");
    if dir.is_dir() {
        Some(dir)
    } else {
        eprintln!("skipped: no Java dist config at {}", dir.display());
        None
    }
}

fn write(dir: &Path, name: &str, text: &str) {
    let path = dir.join(name);
    std::fs::create_dir_all(path.parent().unwrap()).unwrap();
    std::fs::write(path, text).unwrap();
}

#[test]
fn class_table_is_complete() {
    // 16 main classes (Server + 15) and 44 custom ones, like ConfigLoader.init().
    assert_eq!(CLASSES.len(), 60);
    assert_eq!(
        CLASSES.iter().filter(|(_, f)| f.starts_with("Custom/")).count(),
        44
    );
    // Every class is a field of GameConfig (its Debug output names each struct).
    let debug = format!("{:?}", GameConfig::default());
    for (class, _) in CLASSES {
        assert!(
            debug.contains(&format!("{class} {{")),
            "GameConfig has no field of type {class}"
        );
    }
}

#[test]
fn empty_dir_gives_the_java_defaults() {
    let dir = tempfile::tempdir().unwrap();
    let config = GameConfig::load(dir.path()).unwrap();
    assert_eq!(config, GameConfig::default());

    // Defaults taken from the Java source (`config.getX("Key", default)`).
    assert_eq!(config.server.port_game, 7777);
    assert_eq!(config.server.maximum_online_users, 100);
    assert_eq!(config.server.max_characters_number_per_account, 7);
    assert!(config.general.htm_cache);
    assert!(!config.general.gm_startup_invisible);
    assert_eq!(config.general.minimum_chat_level, 20);
    assert_eq!(config.general.alt_lottery_prize, 50_000);
    assert!((config.general.alt_lottery_5_number_rate - 0.6).abs() < f32::EPSILON);
    assert_eq!(config.general.bookmark_consume_item_id, -1);
    assert_eq!(config.player.player_maximum_level, 85);
    assert_eq!(config.player.buffs_max_amount, 20);
    assert!((config.rates.rate_xp - 1.0).abs() < f32::EPSILON);
    assert_eq!(config.auto_play.auto_play_short_range, 600);
    assert_eq!(config.champion_monsters.champ_title, "Champion");
    assert_eq!(config.geo_engine.pathfinding, 0);
}

#[test]
fn values_of_every_type_are_read() {
    let dir = tempfile::tempdir().unwrap();
    write(
        dir.path(),
        "General.ini",
        "GMStartupInvisible = True\nMinimumChatLevel = 3\nAltLotteryPrize = 9000000000\nAltLottery5NumberRate = 0.25\nBBSDefault = _bbsmine\n",
    );
    write(dir.path(), "Player.ini", "MaximumPlayerLevel = 99\n");
    write(
        dir.path(),
        "Custom/AutoPlay.ini",
        "ShortRange = 1\nAutoPlayLoginMessage = hello world\n",
    );
    write(dir.path(), "NPC.ini", "AggroDistanceCheckRange = notanumber\n");
    let config = GameConfig::load(dir.path()).unwrap();

    assert!(config.general.gm_startup_invisible); // bool
    assert_eq!(config.general.minimum_chat_level, 3); // int
    assert_eq!(config.general.alt_lottery_prize, 9_000_000_000); // long
    assert!((config.general.alt_lottery_5_number_rate - 0.25).abs() < f32::EPSILON); // float
    assert_eq!(config.general.bbs_default, "_bbsmine"); // string
    assert_eq!(config.player.player_maximum_level, 99); // byte
    assert_eq!(config.auto_play.auto_play_short_range, 1); // file in Custom/
    assert_eq!(config.auto_play.auto_play_login_message, "hello world");
    // A value that does not parse falls back to the default, like Java.
    assert_eq!(config.npc.aggro_distance_check_range, 1500);
    // Files that are not there keep their defaults.
    assert_eq!(config.server.port_game, 7777);
}

#[test]
fn malformed_unicode_escape_is_an_error() {
    let dir = tempfile::tempdir().unwrap();
    write(dir.path(), "General.ini", "BBSDefault = \\u12\n");
    assert!(GameConfig::load(dir.path()).is_err());
}

#[test]
fn every_class_file_exists_in_dist() {
    let Some(dir) = dist_config_dir() else { return };
    for (class, file) in CLASSES {
        assert!(
            dir.join(file).is_file(),
            "{class}: {file} is not in {}",
            dir.display()
        );
        // Every file parses (the loader would crash on a malformed escape).
        IniFile::load(dir.join(file)).unwrap();
    }
}

#[test]
fn dist_config_loads_with_spot_checks() {
    let Some(dir) = dist_config_dir() else { return };
    let config = GameConfig::load(&dir).unwrap();
    assert_ne!(config, GameConfig::default());

    // Ten or more keys from different files; most differ from the Java default on purpose, so a
    // wrong key or a wrong getter shows up.
    assert_eq!(config.server.port_game, 7777);
    assert_eq!(config.server.maximum_online_users, 2000); // default 100
    assert!(config.general.gm_startup_invisible); // default false
    assert!(!config.general.htm_cache); // default true
    assert_eq!(config.general.minimum_chat_level, 0); // default 20
    assert_eq!(config.general.bookmark_consume_item_id, 20033); // default -1
    assert_eq!(config.general.alt_lottery_prize, 50_000);
    assert_eq!(config.geo_engine.pathfinding, 2); // default 0
    assert_eq!(config.grand_boss.antharas_wait_time, 20); // default 30
    assert_eq!(config.npc.aggro_distance_check_range, 2000); // default 1500
    assert!(config.offline_trade.offline_trade_enable); // default false (Custom/)
    assert_eq!(config.champion_monsters.champion_frequency, 5); // default 0 (Custom/)
    assert!(!config.feature.alt_strict_sevensigns); // default true
    assert_eq!(config.player.warehouse_slots_clan, 200); // default 150
    assert_eq!(config.player.player_maximum_level, 85);
    assert!((config.rates.rate_xp - 1.0).abs() < f32::EPSILON);
}

/// L-09: the hand-ported fields of the core classes read the shipped files.
#[test]
fn dist_config_core_manual_fields() {
    let Some(dir) = dist_config_dir() else { return };
    let config = GameConfig::load(&dir).unwrap();
    let core = &config.manual.core;

    assert_eq!(core.server.datapack_root, ".");
    assert_eq!(core.server.script_root, "./data/scripts");
    assert_eq!(core.server.server_list_type, 0x40);
    assert_eq!(core.server.server_restart_schedule, ["08:00"]);
    assert_eq!(core.server.precautionary_restart_delay, 60_000);
    // chatfilter.txt is in the same folder.
    assert!(!core.server.filter_list.is_empty());
    assert!(core.server.filter_list.iter().all(|word| !word.starts_with('#')));

    assert_eq!(core.general.char_data_store_interval, 15 * 60 * 1000);
    assert_eq!(core.general.default_punish, "KICK");
    assert_eq!(
        core.general.ban_chat_channels,
        ["GENERAL", "SHOUT", "TRADE", "HERO_VOICE", "WHISPER"]
    );
    assert_eq!(core.general.botreport_resetpoint_hour, ["00", "00"]);

    assert_eq!(core.player.enchant_blacklist.len(), 19);
    assert!(core.player.party_xp_cutoff_method.eq_ignore_ascii_case("LEVEL"));
    assert_eq!(core.player.party_xp_cutoff_gaps, [[0, 9], [10, 14], [15, 99]]);
    assert!(core.player.alt_game_cancel_cast && !core.player.alt_game_cancel_bow);

    assert_eq!(core.npc.list_pet_rent_npc, [30827]);
    assert_eq!(core.olympiad.olympiad_classed_reward, [[13722, 50]]);
    assert_eq!(core.olympiad.olympiad_competition_days.len(), 7);
    assert_eq!(core.flood_protector.use_item.protection_interval, 0); // the shipped file; default 4
    assert!(core.pvp.karma_list_nondroppable_items.contains(&57));
    assert_eq!(config.effective_initial_capacity(), 100_000);
}
